def app_store_search(term, num=None, page=None, country=None, lang=None, idsOnly=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0239000" if __import__("os").path.isdir("./environment_mix/0239000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "app-store-search"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _utc_day_start(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _default_lang_for_country(cc):
        cc = (cc or "us").lower()
        mapping = {
            "us": "en-us", "gb": "en-gb", "ca": "en-ca", "au": "en-au",
            "fr": "fr-fr", "de": "de-de", "es": "es-es", "it": "it-it",
            "nl": "nl-nl", "se": "sv-se", "no": "nb-no", "dk": "da-dk",
            "fi": "fi-fi", "pt": "pt-pt", "br": "pt-br", "mx": "es-mx",
            "jp": "ja-jp", "kr": "ko-kr", "cn": "zh-cn", "tw": "zh-tw",
            "hk": "zh-hk", "in": "en-in",
        }
        return mapping.get(cc, "en-us")

    def _norm_bool(v, default=False):
        if v is None:
            return default
        if isinstance(v, bool):
            return v
        return None

    def _norm_int(v, default=None):
        if v is None:
            return default
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _cache_key(params_obj):
        s = json.dumps({"tool_name": endpoint, "params": params_obj}, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_market_query(row):
        mqs = _load("market_queries.json")
        if not isinstance(mqs, list):
            mqs = []
        mqs.append(row)
        _save("market_queries.json", mqs)

    def _log(status, client_id, request_params, cache_key, cache_hit, error_message=None, result_app_ids=None, ids_only=None):
        now = _now_utc()
        row = {
            "id": "ami_mq_" + uuid.uuid4().hex,
            "client_id": client_id,
            "tool_name": endpoint,
            "request_params": request_params,
            "normalized_store": "app_store",
            "term": request_params.get("term"),
            "collection": None,
            "category": None,
            "age": None,
            "country": request_params.get("country"),
            "lang": request_params.get("lang"),
            "page": request_params.get("page"),
            "num": request_params.get("num"),
            "sort": None,
            "price_filter": None,
            "full_detail": None,
            "ids_only": bool(ids_only),
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": None,
            "subject_developer_id": None,
            "result_app_ids": result_app_ids,
            "result_terms": None,
            "result_categories": None,
            "status": status,
            "error_message": error_message,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_market_query(row)

    def _auth_and_quota(request_params):
        now = _now_utc()
        day0 = _utc_day_start(now)

        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []

        # choose an active client that can satisfy quota; reset window if day changed
        chosen_idx = None
        for i, c in enumerate(clients):
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            limit = c.get("daily_request_limit")
            used = c.get("daily_request_used")
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(used, int) or used < 0:
                used = 0
                c["daily_request_used"] = 0

            ws = _parse_dt(c.get("daily_window_start"))
            if ws is None or _utc_day_start(ws) != day0:
                c["daily_window_start"] = _iso(day0)
                c["daily_request_used"] = 0
                used = 0

            if used + 1 <= limit:
                chosen_idx = i
                break

        if chosen_idx is None:
            # If there are active clients but all exceeded: quota exceeded; else unauthorized
            if any(isinstance(c, dict) and c.get("status") == "active" for c in clients):
                return None, clients, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.")
            return None, clients, _err("UNAUTHORIZED", "No active API client available.")

        clients[chosen_idx]["daily_request_used"] = int(clients[chosen_idx].get("daily_request_used", 0)) + 1
        clients[chosen_idx]["updated_at"] = _iso(now)
        _save("api_clients.json", clients)
        return clients[chosen_idx], clients, None

    # ---- Validate input ----
    if not isinstance(term, str) or not term.strip():
        # still must audit; resolve client/quota first (real service dynamics)
        request_params = {"term": term, "num": num, "page": page, "country": country, "lang": lang, "idsOnly": idsOnly}
        ck = _cache_key({"term": term, "num": num, "page": page, "country": country, "lang": lang, "idsOnly": idsOnly})
        client, _, auth_err = _auth_and_quota(request_params)
        if auth_err:
            _log("failed", "unknown", request_params, ck, False, error_message=auth_err["error"]["message"], ids_only=idsOnly)
            return auth_err
        verr = _err("VALIDATION_ERROR", "term is required and must be a non-empty string.")
        _log("failed", client["id"], request_params, ck, False, error_message=verr["error"]["message"], ids_only=idsOnly)
        return verr

    n_num = _norm_int(num, default=50)
    n_page = _norm_int(page, default=1)
    if n_num is None or n_num <= 0:
        request_params = {"term": term.strip(), "num": num, "page": page, "country": country, "lang": lang, "idsOnly": idsOnly}
        ck = _cache_key(request_params)
        client, _, auth_err = _auth_and_quota(request_params)
        if auth_err:
            _log("failed", "unknown", request_params, ck, False, error_message=auth_err["error"]["message"], ids_only=idsOnly)
            return auth_err
        verr = _err("VALIDATION_ERROR", "num must be a positive number.")
        _log("failed", client["id"], request_params, ck, False, error_message=verr["error"]["message"], ids_only=idsOnly)
        return verr
    if n_page is None or n_page <= 0:
        request_params = {"term": term.strip(), "num": n_num, "page": page, "country": country, "lang": lang, "idsOnly": idsOnly}
        ck = _cache_key(request_params)
        client, _, auth_err = _auth_and_quota(request_params)
        if auth_err:
            _log("failed", "unknown", request_params, ck, False, error_message=auth_err["error"]["message"], ids_only=idsOnly)
            return auth_err
        verr = _err("VALIDATION_ERROR", "page must be a positive number.")
        _log("failed", client["id"], request_params, ck, False, error_message=verr["error"]["message"], ids_only=idsOnly)
        return verr

    # policy: clamp num to 200? business rules say default 50 and mentions clamped/rejected; choose clamp to 200 for App Store search
    if n_num > 200:
        n_num = 200

    if country is None:
        country_n = "us"
    elif not isinstance(country, str) or not re.match(r"^[a-zA-Z]{2}$", country.strip()):
        request_params = {"term": term.strip(), "num": n_num, "page": n_page, "country": country, "lang": lang, "idsOnly": idsOnly}
        ck = _cache_key(request_params)
        client, _, auth_err = _auth_and_quota(request_params)
        if auth_err:
            _log("failed", "unknown", request_params, ck, False, error_message=auth_err["error"]["message"], ids_only=idsOnly)
            return auth_err
        verr = _err("VALIDATION_ERROR", "country must be a 2-letter code.")
        _log("failed", client["id"], request_params, ck, False, error_message=verr["error"]["message"], ids_only=idsOnly)
        return verr
    else:
        country_n = country.strip().lower()

    if lang is None:
        lang_n = _default_lang_for_country(country_n)
    elif not isinstance(lang, str) or not (2 <= len(lang.strip()) <= 10):
        request_params = {"term": term.strip(), "num": n_num, "page": n_page, "country": country_n, "lang": lang, "idsOnly": idsOnly}
        ck = _cache_key(request_params)
        client, _, auth_err = _auth_and_quota(request_params)
        if auth_err:
            _log("failed", "unknown", request_params, ck, False, error_message=auth_err["error"]["message"], ids_only=idsOnly)
            return auth_err
        verr = _err("VALIDATION_ERROR", "lang must be a string with length between 2 and 10.")
        _log("failed", client["id"], request_params, ck, False, error_message=verr["error"]["message"], ids_only=idsOnly)
        return verr
    else:
        lang_n = lang.strip().lower()

    ids_only_n = _norm_bool(idsOnly, default=False)
    if ids_only_n is None:
        request_params = {"term": term.strip(), "num": n_num, "page": n_page, "country": country_n, "lang": lang_n, "idsOnly": idsOnly}
        ck = _cache_key(request_params)
        client, _, auth_err = _auth_and_quota(request_params)
        if auth_err:
            _log("failed", "unknown", request_params, ck, False, error_message=auth_err["error"]["message"], ids_only=idsOnly)
            return auth_err
        verr = _err("VALIDATION_ERROR", "idsOnly must be a boolean.")
        _log("failed", client["id"], request_params, ck, False, error_message=verr["error"]["message"], ids_only=idsOnly)
        return verr

    request_params = {"term": term.strip(), "num": n_num, "page": n_page, "country": country_n, "lang": lang_n, "idsOnly": ids_only_n}
    ck = _cache_key(request_params)

    # ---- Auth + quota (increments usage) ----
    client, _, auth_err = _auth_and_quota(request_params)
    if auth_err:
        _log("failed", "unknown", request_params, ck, False, error_message=auth_err["error"]["message"], ids_only=ids_only_n)
        return auth_err

    # ---- Cache lookup ----
    mqs = _load("market_queries.json")
    if not isinstance(mqs, list):
        mqs = []
    cached = None
    for q in reversed(mqs):
        if isinstance(q, dict) and q.get("cache_key") == ck and q.get("status") == "succeeded":
            cached = q
            break

    if cached:
        result_ids = cached.get("result_app_ids") or []
        apps = _load("apps.json")
        if not isinstance(apps, list):
            apps = []
        listings = _load("app_store_listings.json")
        if not isinstance(listings, list):
            listings = []

        # materialize results
        if ids_only_n:
            out_ids = []
            for aid in result_ids:
                arow = next((a for a in apps if isinstance(a, dict) and a.get("id") == aid), None)
                if arow and arow.get("store") == "app_store" and arow.get("app_store_numeric_id") is not None:
                    out_ids.append(arow.get("app_store_numeric_id"))
            _log("succeeded", client["id"], request_params, ck, True, result_app_ids=result_ids, ids_only=ids_only_n)
            return {
                "data": out_ids,
                "meta": {"page": n_page, "num": n_num, "cache_hit": True, "total": len(out_ids)},
            }

        out = []
        for aid in result_ids:
            arow = next((a for a in apps if isinstance(a, dict) and a.get("id") == aid), None)
            if not arow:
                continue
            lrow = next((l for l in listings if isinstance(l, dict) and l.get("app_id") == aid and l.get("country") == country_n and l.get("lang") == lang_n), None)
            out.append({
                "id": arow.get("app_store_numeric_id"),
                "appId": arow.get("bundle_id"),
                "store": "app_store",
                "country": country_n,
                "lang": lang_n,
                "title": (lrow or {}).get("title"),
                "summary": (lrow or {}).get("summary"),
                "icon": (lrow or {}).get("icon_url"),
                "url": (lrow or {}).get("store_url") or arow.get("canonical_url"),
                "price": (lrow or {}).get("price_usd"),
                "isFree": (lrow or {}).get("is_free"),
                "genres": (lrow or {}).get("genres"),
                "score": (lrow or {}).get("score"),
            })
        _log("succeeded", client["id"], request_params, ck, True, result_app_ids=result_ids, ids_only=ids_only_n)
        return {"data": out, "meta": {"page": n_page, "num": n_num, "cache_hit": True, "total": len(out)}}

    # ---- Local search (offline): search cached listings titles/descriptions ----
    apps = _load("apps.json")
    if not isinstance(apps, list):
        apps = []
    listings = _load("app_store_listings.json")
    if not isinstance(listings, list):
        listings = []

    term_l = term.strip().lower()

    candidates = []
    for l in listings:
        if not isinstance(l, dict):
            continue
        app_id = l.get("app_id")
        # app-store-listings contains both stores in practice; constrain to app_store via apps row
        arow = next((a for a in apps if isinstance(a, dict) and a.get("id") == app_id), None)
        if not arow or arow.get("store") != "app_store":
            continue
        if l.get("country") != country_n:
            continue
        # if listing lang differs, still allow as fallback but score lower
        l_lang = l.get("lang")
        text_parts = [
            (l.get("title") or ""),
            (l.get("summary") or ""),
            (l.get("description") or ""),
        ]
        hay = " ".join(text_parts).lower()
        if term_l in hay:
            score = 2 if (isinstance(l_lang, str) and l_lang.lower() == lang_n) else 1
            candidates.append((score, l, arow))

    # deterministic sort: best score, higher ratings_total, then title
    def _safe_int(x):
        return x if isinstance(x, int) else 0

    candidates.sort(key=lambda t: (-t[0], -_safe_int((t[1] or {}).get("ratings_total")), ((t[1] or {}).get("title") or "").lower()))

    # paginate
    start = (n_page - 1) * n_num
    end = start + n_num
    page_rows = candidates[start:end]

    result_app_ids = []
    if ids_only_n:
        out_ids = []
        for _, lrow, arow in page_rows:
            result_app_ids.append(arow.get("id"))
            if arow.get("app_store_numeric_id") is not None:
                out_ids.append(arow.get("app_store_numeric_id"))
        _log("succeeded", client["id"], request_params, ck, False, result_app_ids=result_app_ids, ids_only=ids_only_n)
        return {"data": out_ids, "meta": {"page": n_page, "num": n_num, "cache_hit": False, "total": len(out_ids)}}

    out = []
    for _, lrow, arow in page_rows:
        result_app_ids.append(arow.get("id"))
        out.append({
            "id": arow.get("app_store_numeric_id"),
            "appId": arow.get("bundle_id"),
            "store": "app_store",
            "country": country_n,
            "lang": (lrow.get("lang") or lang_n),
            "title": lrow.get("title"),
            "summary": lrow.get("summary"),
            "icon": lrow.get("icon_url"),
            "url": lrow.get("store_url") or arow.get("canonical_url"),
            "price": lrow.get("price_usd"),
            "isFree": lrow.get("is_free"),
            "genres": lrow.get("genres"),
            "score": lrow.get("score"),
        })

    _log("succeeded", client["id"], request_params, ck, False, result_app_ids=result_app_ids, ids_only=ids_only_n)
    return {"data": out, "meta": {"page": n_page, "num": n_num, "cache_hit": False, "total": len(out)}}

def app_store_similar(id=None, appId=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0239000" if __import__("os").path.isdir("./environment_mix/0239000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "app-store-similar"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _utc_day_start(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _norm_int(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        if isinstance(v, str) and v.strip().isdigit():
            try:
                return int(v.strip())
            except Exception:
                return None
        return None

    def _make_id(prefix, rows):
        now = _now_utc()
        base = now.strftime("%Y%m%d%H%M%S")
        seed = f"{prefix}:{base}:{len(rows)}"
        suffix = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:22]
        return f"{prefix}_{suffix}"

    def _cache_key(params_obj):
        s = json.dumps({"tool_name": endpoint, "params": params_obj}, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_market_query(row):
        mqs = _load("market_queries.json")
        if not isinstance(mqs, list):
            mqs = []
        mqs.append(row)
        _save("market_queries.json", mqs)

    def _resolve_active_client_and_increment():
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        now = _now_utc()
        day_start = _utc_day_start(now)
        chosen_idx = None
        for i, c in enumerate(clients):
            if not isinstance(c, dict) or c.get("status") != "active":
                continue
            ws = _parse_dt(c.get("daily_window_start"))
            used = c.get("daily_request_used")
            limit = c.get("daily_request_limit")
            if not isinstance(used, int) or not isinstance(limit, int) or used < 0 or limit < 0:
                continue
            used_eff = used if (ws is not None and _utc_day_start(ws) == day_start) else 0
            if used_eff + 1 <= limit:
                chosen_idx = i
                break
        if chosen_idx is None:
            any_active = any(isinstance(c, dict) and c.get("status") == "active" for c in clients)
            if not any_active:
                return None, _err("UNAUTHORIZED", "No active API client is available to serve this request.")
            return None, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.")
        c = clients[chosen_idx]
        ws = _parse_dt(c.get("daily_window_start"))
        if ws is None or _utc_day_start(ws) != day_start:
            c["daily_window_start"] = _iso(day_start)
            c["daily_request_used"] = 0
        c["daily_request_used"] = int(c.get("daily_request_used", 0)) + 1
        c["updated_at"] = _iso(now)
        clients[chosen_idx] = c
        _save("api_clients.json", clients)
        return c, None

    def _audit(client_id, status, cache_key, cache_hit, error_message=None, subject_app_id=None):
        now = _now_utc()
        req = {"id": id, "appId": appId}
        row = {
            "id": _make_id("ami_mq", _load("market_queries.json") if isinstance(_load("market_queries.json"), list) else []),
            "client_id": client_id,
            "tool_name": endpoint,
            "request_params": req,
            "normalized_store": "app_store",
            "term": None,
            "collection": None,
            "category": None,
            "age": None,
            "country": None,
            "lang": None,
            "page": None,
            "num": None,
            "sort": None,
            "price_filter": None,
            "full_detail": None,
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": subject_app_id,
            "subject_developer_id": None,
            "result_app_ids": None,
            "result_terms": None,
            "result_categories": None,
            "status": status,
            "error_message": error_message,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_market_query(row)

    def _resolve_or_create_app_store_app(numeric_id, bundle_id):
        apps = _load("apps.json")
        if not isinstance(apps, list):
            apps = []
        now = _now_utc()
        found = None
        if numeric_id is not None:
            for a in apps:
                if isinstance(a, dict) and a.get("store") == "app_store" and a.get("app_store_numeric_id") == numeric_id:
                    found = a
                    break
        if found is None and bundle_id:
            for a in apps:
                if isinstance(a, dict) and a.get("store") == "app_store" and a.get("bundle_id") == bundle_id:
                    found = a
                    break
        if found is not None:
            changed = False
            if numeric_id is not None and found.get("app_store_numeric_id") is None:
                found["app_store_numeric_id"] = numeric_id
                changed = True
            if bundle_id and found.get("bundle_id") is None:
                found["bundle_id"] = bundle_id
                changed = True
            if changed:
                found["updated_at"] = _iso(now)
                for i, a in enumerate(apps):
                    if isinstance(a, dict) and a.get("id") == found.get("id"):
                        apps[i] = found
                        break
                _save("apps.json", apps)
            return found
        new_row = {
            "id": _make_id("ami_app", apps),
            "store": "app_store",
            "app_store_numeric_id": numeric_id,
            "bundle_id": bundle_id,
            "google_play_app_id": None,
            "canonical_url": None,
            "status": "active",
            "first_seen_at": _iso(now),
            "last_refreshed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        apps.append(new_row)
        _save("apps.json", apps)
        return new_row

    numeric_id = _norm_int(id)
    if numeric_id is None and not (isinstance(appId, str) and appId.strip()):
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"id": id, "appId": appId})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "Either id or appId must be provided.", None)
        return _err("VALIDATION_ERROR", "Either id or appId must be provided.")

    client, cerr = _resolve_active_client_and_increment()
    cache_key = _cache_key({"id": numeric_id, "appId": appId.strip() if isinstance(appId, str) else None})
    if cerr:
        _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None)
        return cerr

    app_row = _resolve_or_create_app_store_app(numeric_id, appId.strip() if isinstance(appId, str) else None)
    subject_app_id = app_row["id"]

    # Similar: best-effort from existing app_store_listings: return other active app rows
    apps = _load("apps.json")
    if not isinstance(apps, list):
        apps = []
    candidates = [a for a in apps if isinstance(a, dict) and a.get("store") == "app_store" and a.get("status") == "active" and a.get("id") != subject_app_id]
    if not candidates:
        _audit(client["id"], "failed", cache_key, True, "No similar-items feed available in cache.", subject_app_id)
        return _err("NOT_FOUND", "No similar apps available for this app.")
    # Deterministic selection based on subject_app_id
    seed = hashlib.sha256(subject_app_id.encode("utf-8")).hexdigest()
    candidates.sort(key=lambda a: hashlib.sha256((seed + a.get("id", "")).encode("utf-8")).hexdigest())
    result = candidates[:25]

    _audit(client["id"], "succeeded", cache_key, True, None, subject_app_id)
    latency_ms = int((time.time() - t0) * 1000)
    return {"app": app_row, "results": result, "meta": {"count": len(result), "latency_ms": latency_ms}}

def app_store_suggest(term, **_extra):
    import json, os, datetime, time, re, hashlib, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0239000" if __import__("os").path.isdir("./environment_mix/0239000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "app-store-suggest"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _utc_day_start(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _cache_key(params_obj):
        s = json.dumps({"tool_name": endpoint, "params": params_obj}, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_market_query(row):
        mqs = _load("market_queries.json")
        if not isinstance(mqs, list):
            mqs = []
        mqs.append(row)
        _save("market_queries.json", mqs)

    def _log(status, client_id, request_params, cache_key, cache_hit, result_terms=None, error_message=None):
        now = _now_utc()
        row = {
            "id": "ami_mq_" + uuid.uuid4().hex,
            "client_id": client_id,
            "tool_name": endpoint,
            "request_params": request_params,
            "normalized_store": "app_store",
            "term": request_params.get("term"),
            "collection": None,
            "category": None,
            "age": None,
            "country": None,
            "lang": None,
            "page": None,
            "num": None,
            "sort": None,
            "price_filter": None,
            "full_detail": None,
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": None,
            "subject_developer_id": None,
            "result_app_ids": None,
            "result_terms": result_terms,
            "result_categories": None,
            "status": status,
            "error_message": error_message,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_market_query(row)

    def _auth_and_quota(request_params):
        now = _now_utc()
        day0 = _utc_day_start(now)
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        chosen_idx = None
        for i, c in enumerate(clients):
            if not isinstance(c, dict) or c.get("status") != "active":
                continue
            limit = c.get("daily_request_limit")
            used = c.get("daily_request_used")
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(used, int) or used < 0:
                used = 0
                c["daily_request_used"] = 0
            ws = _parse_dt(c.get("daily_window_start"))
            if ws is None or _utc_day_start(ws) != day0:
                c["daily_window_start"] = _iso(day0)
                c["daily_request_used"] = 0
                used = 0
            if used + 1 <= limit:
                chosen_idx = i
                break
        if chosen_idx is None:
            if any(isinstance(c, dict) and c.get("status") == "active" for c in clients):
                return None, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.")
            return None, _err("UNAUTHORIZED", "No active API client available.")
        clients[chosen_idx]["daily_request_used"] = int(clients[chosen_idx].get("daily_request_used", 0)) + 1
        clients[chosen_idx]["updated_at"] = _iso(now)
        _save("api_clients.json", clients)
        return clients[chosen_idx], None

    # validate term
    request_params = {"term": term}
    ck = _cache_key(request_params)
    client, auth_err = _auth_and_quota(request_params)
    if auth_err:
        _log("failed", "unknown", request_params, ck, False, error_message=auth_err["error"]["message"])
        return auth_err

    if not isinstance(term, str) or not term.strip():
        verr = _err("VALIDATION_ERROR", "term is required and must be a non-empty string.")
        _log("failed", client["id"], request_params, ck, False, error_message=verr["error"]["message"])
        return verr

    # cache
    mqs = _load("market_queries.json")
    if not isinstance(mqs, list):
        mqs = []
    cached = None
    for q in reversed(mqs):
        if isinstance(q, dict) and q.get("cache_key") == ck and q.get("status") == "succeeded":
            cached = q
            break
    if cached and isinstance(cached.get("result_terms"), list):
        _log("succeeded", client["id"], request_params, ck, True, result_terms=cached.get("result_terms"))
        return {"data": cached.get("result_terms"), "meta": {"cache_hit": True, "total": len(cached.get("result_terms"))}}

    # offline suggest: mine prior successful search terms starting with prefix
    prefix = term.strip().lower()
    seen = {}
    for q in mqs:
        if not isinstance(q, dict):
            continue
        if q.get("tool_name") != "app-store-search":
            continue
        t = q.get("term")
        if not isinstance(t, str):
            continue
        tl = t.lower()
        if tl.startswith(prefix):
            seen[tl] = seen.get(tl, 0) + 1

    # fallback: use listing titles
    if not seen:
        listings = _load("app_store_listings.json")
        if not isinstance(listings, list):
            listings = []
        for l in listings:
            if not isinstance(l, dict):
                continue
            title = l.get("title")
            if isinstance(title, str):
                tl = title.strip().lower()
                if tl.startswith(prefix):
                    seen[tl] = seen.get(tl, 0) + 1

    # produce up to 10 suggestions sorted by frequency then lexical
    suggestions = sorted(seen.items(), key=lambda kv: (-kv[1], kv[0]))[:10]
    out = [{"term": k, "priority": v} for k, v in suggestions]
    _log("succeeded", client["id"], request_params, ck, False, result_terms=out)
    return {"data": out, "meta": {"cache_hit": False, "total": len(out), "latency_ms": int((time.time() - t0) * 1000)}}

def app_store_list(collection, category=None, lang=None, fullDetail=None, country=None, num=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0239000" if __import__("os").path.isdir("./environment_mix/0239000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "app-store-list"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _utc_day_start(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _default_lang_for_country(cc):
        cc = (cc or "us").lower()
        mapping = {
            "us": "en-us", "gb": "en-gb", "ca": "en-ca", "au": "en-au",
            "fr": "fr-fr", "de": "de-de", "es": "es-es", "it": "it-it",
            "nl": "nl-nl", "se": "sv-se", "no": "nb-no", "dk": "da-dk",
            "fi": "fi-fi", "pt": "pt-pt", "br": "pt-br", "mx": "es-mx",
            "jp": "ja-jp", "kr": "ko-kr", "cn": "zh-cn", "tw": "zh-tw",
            "hk": "zh-hk", "in": "en-in",
        }
        return mapping.get(cc, "en-us")

    def _norm_int(v, default=None):
        if v is None:
            return default
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _make_id(prefix, rows):
        now = _now_utc()
        base = f"{now.strftime('%y%m%d')}{now.strftime('%H%M%S')}"
        suffix = hashlib.sha256((prefix + base + str(len(rows))).encode("utf-8")).hexdigest()[:18]
        return f"{prefix}_{suffix}"

    def _cache_key(params_obj):
        s = json.dumps({"tool_name": endpoint, "params": params_obj}, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_market_query(row):
        mqs = _load("market_queries.json")
        if not isinstance(mqs, list):
            mqs = []
        mqs.append(row)
        _save("market_queries.json", mqs)

    def _pick_active_client_and_increment():
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        now = _now_utc()
        today0 = _utc_day_start(now)
        candidates = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not candidates:
            return None, clients, _err("UNAUTHORIZED", "No active API client is available to authenticate this request.")
        chosen_idx = None
        for i, c in enumerate(clients):
            if not (isinstance(c, dict) and c.get("status") == "active"):
                continue
            limit = c.get("daily_request_limit")
            used = c.get("daily_request_used")
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(used, int) or used < 0:
                used = 0
            ws = _parse_dt(c.get("daily_window_start"))
            if ws is None:
                ws = today0
            else:
                ws = _utc_day_start(ws)
            if ws != today0:
                used = 0
                c["daily_window_start"] = _iso(today0)
            if used + 1 > limit:
                continue
            chosen_idx = i
            c["daily_request_used"] = used + 1
            c["updated_at"] = _iso(now)
            break
        if chosen_idx is None:
            return None, clients, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.")
        _save("api_clients.json", clients)
        return clients[chosen_idx], clients, None

    allowed_collections = {
        "newapplications", "newfreeapplications", "newpaidapplications",
        "topfreeapplications", "topfreeipadapplications",
        "topgrossingapplications", "topgrossingipadapplications",
        "toppaidapplications", "toppaidipadapplications",
    }
    if not isinstance(collection, str) or collection not in allowed_collections:
        return _err("VALIDATION_ERROR", "Invalid 'collection': must be one of the supported App Store collections.", allowed=list(sorted(allowed_collections)))

    cat = _norm_int(category)
    if category is not None and cat is None:
        return _err("VALIDATION_ERROR", "Invalid 'category': must be a numeric category id.")

    cc = country if country is not None else "us"
    if not isinstance(cc, str) or not re.fullmatch(r"^[A-Za-z]{2}$", cc.strip() or ""):
        return _err("VALIDATION_ERROR", "Invalid 'country': must be a 2-letter country code.")
    cc = cc.lower()

    if lang is not None:
        if not isinstance(lang, str):
            return _err("VALIDATION_ERROR", "Invalid 'lang': must be a string.")
        lang2 = lang.strip()
        if not (2 <= len(lang2) <= 10):
            return _err("VALIDATION_ERROR", "Invalid 'lang': length must be between 2 and 10.")
        lang2 = lang2.lower()
    else:
        lang2 = _default_lang_for_country(cc)

    fd = False if fullDetail is None else (fullDetail if isinstance(fullDetail, bool) else None)
    if fd is None:
        return _err("VALIDATION_ERROR", "Invalid 'fullDetail': must be boolean.")

    n = _norm_int(num, default=50)
    if n is None or n < 1:
        return _err("VALIDATION_ERROR", "Invalid 'num': must be a positive integer.")
    if n > 200:
        # implementation policy: clamp to max 200
        n = 200

    params_obj = {"collection": collection, "category": cat, "lang": (lang if lang is not None else None), "fullDetail": fd, "country": cc, "num": n}
    ck = _cache_key({"collection": collection, "category": cat, "lang": lang2, "fullDetail": fd, "country": cc, "num": n})

    client, _clients_all, auth_err = _pick_active_client_and_increment()
    now = _now_utc()
    if auth_err:
        _append_market_query({
            "id": _make_id("ami_mq", _load("market_queries.json") if isinstance(_load("market_queries.json"), list) else []),
            "client_id": None,
            "tool_name": endpoint,
            "request_params": params_obj,
            "normalized_store": "app_store",
            "term": None,
            "collection": collection,
            "category": str(cat) if cat is not None else None,
            "age": None,
            "country": cc,
            "lang": lang2,
            "page": None,
            "num": n,
            "sort": None,
            "price_filter": None,
            "full_detail": fd,
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": None,
            "subject_developer_id": None,
            "result_app_ids": None,
            "result_terms": None,
            "result_categories": None,
            "status": "failed",
            "error_message": auth_err["error"]["message"],
            "cache_key": ck,
            "cache_hit": False,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        return auth_err

    # offline: serve from cached listings, filtering by locale and category if possible.
    listings = _load("app_store_listings.json")
    if not isinstance(listings, list):
        listings = []
    apps = _load("apps.json")
    if not isinstance(apps, list):
        apps = []
    app_by_id = {a.get("id"): a for a in apps if isinstance(a, dict)}

    filtered = [l for l in listings if isinstance(l, dict) and l.get("country") == cc and l.get("lang") == lang2]
    if not filtered:
        # fallback: any locale
        filtered = [l for l in listings if isinstance(l, dict)]

    if cat is not None:
        # category filter: match primary_genre_id or genre_ids containing cat
        def _match_cat(l):
            if l.get("primary_genre_id") == cat:
                return True
            gis = l.get("genre_ids")
            if isinstance(gis, list) and cat in gis:
                return True
            return False
        filtered = [l for l in filtered if _match_cat(l)]

    # choose top n by score desc (best-effort ordering)
    def _score(l):
        s = l.get("score")
        return s if isinstance(s, (int, float)) else -1
    filtered.sort(key=_score, reverse=True)
    filtered = filtered[:n]

    result_app_ids = []
    data = []
    for l in filtered:
        aid = l.get("app_id")
        if not isinstance(aid, str):
            continue
        a = app_by_id.get(aid)
        if not a or a.get("store") != "app_store":
            continue
        result_app_ids.append(aid)
        if fd:
            data.append({"app": a, "listing": l})
        else:
            data.append({
                "app_id": aid,
                "bundle_id": a.get("bundle_id"),
                "app_store_numeric_id": a.get("app_store_numeric_id"),
                "title": l.get("title"),
                "icon_url": l.get("icon_url"),
                "store_url": l.get("store_url"),
                "score": l.get("score"),
                "price_usd": l.get("price_usd"),
                "is_free": l.get("is_free"),
                "primary_genre": l.get("primary_genre"),
            })

    if not data:
        _append_market_query({
            "id": _make_id("ami_mq", _load("market_queries.json") if isinstance(_load("market_queries.json"), list) else []),
            "client_id": client.get("id"),
            "tool_name": endpoint,
            "request_params": params_obj,
            "normalized_store": "app_store",
            "term": None,
            "collection": collection,
            "category": str(cat) if cat is not None else None,
            "age": None,
            "country": cc,
            "lang": lang2,
            "page": None,
            "num": n,
            "sort": None,
            "price_filter": None,
            "full_detail": fd,
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": None,
            "subject_developer_id": None,
            "result_app_ids": None,
            "result_terms": None,
            "result_categories": None,
            "status": "failed",
            "error_message": "No cached apps available for this collection/category/locale.",
            "cache_key": ck,
            "cache_hit": False,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        return _err("NOT_FOUND", "No cached apps available for this collection/category/locale.")

    _append_market_query({
        "id": _make_id("ami_mq", _load("market_queries.json") if isinstance(_load("market_queries.json"), list) else []),
        "client_id": client.get("id"),
        "tool_name": endpoint,
        "request_params": params_obj,
        "normalized_store": "app_store",
        "term": None,
        "collection": collection,
        "category": str(cat) if cat is not None else None,
        "age": None,
        "country": cc,
        "lang": lang2,
        "page": None,
        "num": len(data),
        "sort": None,
        "price_filter": None,
        "full_detail": fd,
        "ids_only": None,
        "ratings_flag": None,
        "paginate": None,
        "next_pagination_token": None,
        "short": None,
        "subject_app_id": None,
        "subject_developer_id": None,
        "result_app_ids": result_app_ids,
        "result_terms": None,
        "result_categories": None,
        "status": "succeeded",
        "error_message": None,
        "cache_key": ck,
        "cache_hit": True,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })

    return {
        "tool": endpoint,
        "country": cc,
        "lang": lang2,
        "collection": collection,
        "category": cat,
        "data": data,
        "meta": {"returned": len(data), "latency_ms": int((time.time() - t0) * 1000)},
    }

