                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    def _dt_str(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _today_start_utc(dt):
        return datetime.datetime(dt.year, dt.month, dt.day)

    def _norm_lang(x):
        if x is None:
            return None
        return str(x).strip()

    def _norm_country(x):
        if x is None:
            return None
        return str(x).strip()

    def _make_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _cache_key(tool_name, params_obj):
        s = json.dumps({"tool": tool_name, "params": params_obj}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _request_log_append(client_id, tool_name, params_obj, status, error_code=None, error_message=None, cache_key=None, cache_hit=None):
        queries = _load("market_queries.json")
        row = {
            "id": _make_id("mq"),
            "client_id": client_id,
            "tool_name": tool_name,
            "request_params": params_obj,
            "normalized_store": "google_play",
            "term": params_obj.get("term"),
            "collection": None,
            "category": None,
            "age": None,
            "country": params_obj.get("country"),
            "lang": params_obj.get("lang"),
            "page": None,
            "num": params_obj.get("num"),
            "sort": None,
            "price_filter": params_obj.get("price"),
            "full_detail": params_obj.get("fullDetail"),
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": None,
            "subject_developer_id": None,
            "result_app_ids": None,
            "result_terms": None,
            "result_categories": None,
            "status": status,
            "error_message": (error_message if status == "failed" else None),
            "cache_key": (cache_key or _make_id("ck")),
            "cache_hit": bool(cache_hit) if cache_hit is not None else False,
            "created_at": _dt_str(now),
            "updated_at": _dt_str(now),
        }
        queries.append(row)
        _save("market_queries.json", queries)
        return row

    # ---- Validate inputs ----
    if not isinstance(term, str) or not term.strip():
        # Attempt to log against some authorized client if possible; otherwise return directly.
        clients = _load("api_clients.json")
        any_active = next((c for c in clients if c.get("status") == "active"), None)
        if any_active:
            params_obj = {
                "term": term, "price": price if price is not None else "all",
                "num": num if num is not None else 20,
                "lang": lang if lang is not None else "en",
                "country": country if country is not None else "us",
                "fullDetail": fullDetail if fullDetail is not None else False,
            }
            ck = _cache_key("google-play-search", params_obj)
            _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                error_code="VALIDATION_ERROR", error_message="term is required and must be a non-empty string",
                                cache_key=ck, cache_hit=False)
        return _err("VALIDATION_ERROR", "term is required and must be a non-empty string")

    if price is None:
        price = "all"
    if not isinstance(price, str) or price not in ("all", "free", "paid"):
        clients = _load("api_clients.json")
        any_active = next((c for c in clients if c.get("status") == "active"), None)
        if any_active:
            params_obj = {
                "term": term, "price": price,
                "num": num if num is not None else 20,
                "lang": lang if lang is not None else "en",
                "country": country if country is not None else "us",
                "fullDetail": fullDetail if fullDetail is not None else False,
            }
            ck = _cache_key("google-play-search", params_obj)
            _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                error_code="VALIDATION_ERROR", error_message="price must be one of: all, free, paid",
                                cache_key=ck, cache_hit=False)
        return _err("VALIDATION_ERROR", "price must be one of: all, free, paid")

    if num is None:
        num = 20
    if isinstance(num, bool) or not isinstance(num, (int, float)):
        clients = _load("api_clients.json")
        any_active = next((c for c in clients if c.get("status") == "active"), None)
        if any_active:
            params_obj = {"term": term, "price": price, "num": num, "lang": lang or "en", "country": country or "us", "fullDetail": bool(fullDetail) if fullDetail is not None else False}
            ck = _cache_key("google-play-search", params_obj)
            _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                error_code="VALIDATION_ERROR", error_message="num must be a number",
                                cache_key=ck, cache_hit=False)
        return _err("VALIDATION_ERROR", "num must be a number")
    try:
        num_i = int(num)
    except Exception:
        num_i = None
    if num_i is None or num_i < 1:
        clients = _load("api_clients.json")
        any_active = next((c for c in clients if c.get("status") == "active"), None)
        if any_active:
            params_obj = {"term": term, "price": price, "num": num, "lang": lang or "en", "country": country or "us", "fullDetail": bool(fullDetail) if fullDetail is not None else False}
            ck = _cache_key("google-play-search", params_obj)
            _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                error_code="VALIDATION_ERROR", error_message="num must be >= 1",
                                cache_key=ck, cache_hit=False)
        return _err("VALIDATION_ERROR", "num must be >= 1")
    # Policy: clamp to max (rather than reject)
    if num_i > 250:
        num_i = 250

    if lang is None:
        lang = "en"
    lang = _norm_lang(lang)
    if not isinstance(lang, str) or not (2 <= len(lang) <= 10):
        clients = _load("api_clients.json")
        any_active = next((c for c in clients if c.get("status") == "active"), None)
        if any_active:
            params_obj = {"term": term, "price": price, "num": num_i, "lang": lang, "country": country or "us", "fullDetail": bool(fullDetail) if fullDetail is not None else False}
            ck = _cache_key("google-play-search", params_obj)
            _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                error_code="VALIDATION_ERROR", error_message="lang must be a string length 2..10",
                                cache_key=ck, cache_hit=False)
        return _err("VALIDATION_ERROR", "lang must be a string length 2..10")

    if country is None:
        country = "us"
    country = _norm_country(country)
    if not isinstance(country, str) or re.fullmatch(r"^[a-zA-Z]{2}$", country) is None:
        clients = _load("api_clients.json")
        any_active = next((c for c in clients if c.get("status") == "active"), None)
        if any_active:
            params_obj = {"term": term, "price": price, "num": num_i, "lang": lang, "country": country, "fullDetail": bool(fullDetail) if fullDetail is not None else False}
            ck = _cache_key("google-play-search", params_obj)
            _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                error_code="VALIDATION_ERROR", error_message="country must be a 2-letter code",
                                cache_key=ck, cache_hit=False)
        return _err("VALIDATION_ERROR", "country must be a 2-letter code")
    country = country.lower()

    if fullDetail is None:
        fullDetail = False
    if not isinstance(fullDetail, bool):
        clients = _load("api_clients.json")
        any_active = next((c for c in clients if c.get("status") == "active"), None)
        if any_active:
            params_obj = {"term": term, "price": price, "num": num_i, "lang": lang, "country": country, "fullDetail": fullDetail}
            ck = _cache_key("google-play-search", params_obj)
            _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                error_code="VALIDATION_ERROR", error_message="fullDetail must be a boolean",
                                cache_key=ck, cache_hit=False)
        return _err("VALIDATION_ERROR", "fullDetail must be a boolean")

    params_obj = {"term": term.strip(), "price": price, "num": num_i, "lang": lang, "country": country, "fullDetail": fullDetail}
    ck = _cache_key("google-play-search", params_obj)

    # ---- Authenticate ambiently to any active client that can serve (active + quota available) ----
    clients = _load("api_clients.json")
    client_idx = None
    for i, c in enumerate(clients):
        if c.get("status") != "active":
            continue
        limit = c.get("daily_request_limit")
        used = c.get("daily_request_used")
        if not isinstance(limit, int) or limit < 0 or not isinstance(used, int) or used < 0:
            continue
        ws = _parse_dt(c.get("daily_window_start"))
        if ws is None:
            continue
        # reset window if needed
        today0 = _today_start_utc(now)
        if ws != today0:
            # would reset; always leaves used at 0 and window start today
            used_eff = 0
            limit_eff = limit
        else:
            used_eff = used
            limit_eff = limit
        if used_eff + 1 <= limit_eff:
            client_idx = i
            break

    if client_idx is None:
        # Log against some active client (or none) and return UNAUTHORIZED vs QUOTA:
        any_active = next((c for c in clients if c.get("status") == "active"), None)
        if any_active:
            # Determine if it's quota vs no valid client row
            ws = _parse_dt(any_active.get("daily_window_start"))
            limit = any_active.get("daily_request_limit")
            used = any_active.get("daily_request_used")
            today0 = _today_start_utc(now)
            if isinstance(limit, int) and isinstance(used, int) and ws is not None:
                used_eff = 0 if ws != today0 else used
                if used_eff + 1 > limit:
                    _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                        error_code="QUOTA_EXCEEDED", error_message="Daily request quota exceeded",
                                        cache_key=ck, cache_hit=False)
                    return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
            _request_log_append(any_active.get("id"), "google-play-search", params_obj, "failed",
                                error_code="UNAUTHORIZED", error_message="No active client available for this request",
                                cache_key=ck, cache_hit=False)
        return _err("UNAUTHORIZED", "No active client available for this request")

    client = clients[client_idx]
    # reset window if needed and increment atomically (best-effort single-process file store)
    ws = _parse_dt(client.get("daily_window_start"))
    today0 = _today_start_utc(now)
    if ws != today0:
        client["daily_window_start"] = _dt_str(today0)
        client["daily_request_used"] = 0
    if client["daily_request_used"] + 1 > client["daily_request_limit"]:
        _save("api_clients.json", clients)
        _request_log_append(client.get("id"), "google-play-search", params_obj, "failed",
                            error_code="QUOTA_EXCEEDED", error_message="Daily request quota exceeded",
                            cache_key=ck, cache_hit=False)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")
    client["daily_request_used"] += 1
    client["updated_at"] = _dt_str(now)
    _save("api_clients.json", clients)

    # ---- Cache check (market_queries unique(cache_key)) ----
    queries = _load("market_queries.json")
    cached = next((q for q in queries if q.get("cache_key") == ck and q.get("status") == "succeeded"), None)

    apps = _load("apps.json")
    listings = _load("app_store_listings.json")  # used as unified listing snapshot table

    def _ensure_gp_app(app_id_str):
        nonlocal apps
        for a in apps:
            if a.get("store") == "google_play" and a.get("google_play_app_id") == app_id_str:
                return a
        # create
        new_id = _make_id("app")
        row = {
            "id": new_id,
            "store": "google_play",
            "app_store_numeric_id": None,
            "bundle_id": None,
            "google_play_app_id": app_id_str,
            "canonical_url": f"https://play.google.com/store/apps/details?id={app_id_str}",
            "status": "active",
            "first_seen_at": _dt_str(now),
            "last_refreshed_at": None,
            "created_at": _dt_str(now),
            "updated_at": _dt_str(now),
        }
        apps.append(row)
        return row

    def _get_or_create_listing(app_row, country_code, lang_code):
        nonlocal listings
        for l in listings:
            if l.get("app_id") == app_row.get("id") and l.get("country") == country_code and l.get("lang") == lang_code:
                return l
        row = {
            "id": _make_id("lst"),
            "app_id": app_row.get("id"),
            "developer_id": None,
            "country": country_code,
            "lang": lang_code,
            "title": None,
            "summary": None,
            "description": None,
            "description_html": None,
            "icon_url": None,
            "store_url": app_row.get("canonical_url"),
            "price_usd": None,
            "currency": None,
            "price_text": None,
            "is_free": None,
            "genres": None,
            "genre_ids": None,
            "primary_genre": None,
            "primary_genre_id": None,
            "content_rating": None,
            "installs": None,
            "min_installs": None,
            "max_installs": None,
            "score": None,
            "score_text": None,
            "ratings_total": None,
            "ratings_histogram": None,
            "version_history": None,
            "privacy_details": None,
            "permissions": None,
            "data_safety": None,
            "status": "failed",  # unknown until refreshed; but must be valid
            "source_fetched_at": None,
            "expires_at": None,
            "created_at": _dt_str(now),
            "updated_at": _dt_str(now),
        }
        listings.append(row)
        return row

    results = []
    result_app_ids = []

    if cached and isinstance(cached.get("result_app_ids"), list):
        # serve from cache best-effort
        app_ids = cached.get("result_app_ids")[:num_i]
        for aid in app_ids:
            a = next((x for x in apps if x.get("id") == aid and x.get("store") == "google_play"), None)
            if not a:
                continue
            l = next((x for x in listings if x.get("app_id") == aid and x.get("country") == country and x.get("lang") == lang), None)
            obj = {
                "appId": a.get("google_play_app_id"),
                "app_id": a.get("id"),
                "store": "google_play",
                "canonicalUrl": a.get("canonical_url"),
                "title": (l.get("title") if l else None),
                "summary": (l.get("summary") if l else None),
                "icon": (l.get("icon_url") if l else None),
            }
            if fullDetail:
                obj["details"] = (l if l else None)
            results.append(obj)
            result_app_ids.append(aid)

        mq = _request_log_append(client.get("id"), "google-play-search", params_obj, "succeeded",
                                 cache_key=ck, cache_hit=True)
        # persist result_app_ids for this invocation row (not cached row)
        queries = _load("market_queries.json")
        for q in queries:
            if q.get("id") == mq.get("id"):
                q["result_app_ids"] = result_app_ids
                q["updated_at"] = _dt_str(now)
                break
        _save("market_queries.json", queries)

        return {
            "results": results,
            "meta": {"term": term.strip(), "num": len(results), "requested_num": num_i, "country": country, "lang": lang, "price": price, "fullDetail": fullDetail, "cache_hit": True},
            "query": {"id": mq.get("id"), "cache_key": ck},
        }

    # ---- No upstream available offline: perform local index search over cached listing snapshots ----
    # Search over google_play listings by term in title/description/summary; only those linked to google_play apps.
    term_l = term.strip().lower()

    app_by_id = {a.get("id"): a for a in apps if a.get("store") == "google_play" and a.get("status") in ("active", "removed")}
    scored = []
    for l in listings:
        aid = l.get("app_id")
        if aid not in app_by_id:
            continue
        if l.get("country") != country or l.get("lang") != lang:
            continue
        # Simple scoring
        title = (l.get("title") or "")
        summary = (l.get("summary") or "")
        desc = (l.get("description") or "")
        hay = (title + "\n" + summary + "\n" + desc).lower()
        if term_l not in hay:
            continue
        score = 0
        if term_l in title.lower():
            score += 3
        if term_l in summary.lower():
            score += 2
        if term_l in desc.lower():
            score += 1
        # price filter best-effort from is_free / price_usd
        if price == "free":
            if l.get("is_free") is False:
                continue
            if l.get("is_free") is None and (l.get("price_usd") not in (None, 0)):
                continue
        elif price == "paid":
            if l.get("is_free") is True:
                continue
            if l.get("is_free") is None and (l.get("price_usd") in (None, 0)):
                continue
        scored.append((score, l))

    scored.sort(key=lambda x: (-x[0], x[1].get("updated_at") or "", x[1].get("id") or ""))

    for _, l in scored[:num_i]:
        a = app_by_id.get(l.get("app_id"))
        if not a:
            continue
        obj = {
            "appId": a.get("google_play_app_id"),
            "app_id": a.get("id"),
            "store": "google_play",
            "canonicalUrl": a.get("canonical_url"),
            "title": l.get("title"),
            "summary": l.get("summary"),
            "icon": l.get("icon_url"),
        }
        if fullDetail:
            obj["details"] = l
        results.append(obj)
        result_app_ids.append(a.get("id"))

    # Ensure no duplicate cache_key (unique constraint): if exists, mark this query as cache_hit=False but use unique cache_key with suffix
    existing_ck = any(q.get("cache_key") == ck for q in _load("market_queries.json"))
    ck_to_use = ck if not existing_ck else hashlib.sha256((ck + "|" + uuid.uuid4().hex).encode("utf-8")).hexdigest()

    mq = _request_log_append(client.get("id"), "google-play-search", params_obj, "succeeded",
                             cache_key=ck_to_use, cache_hit=False)

    # Store ordered app ids in market_queries.result_app_ids and persist
    queries = _load("market_queries.json")
    for q in queries:
        if q.get("id") == mq.get("id"):
            q["result_app_ids"] = result_app_ids
            q["updated_at"] = _dt_str(now)
            break
    _save("market_queries.json", queries)

    # No mutation to apps/listings on search unless we actually upsert returned items from upstream; offline we only read.

    _ = t0  # latency measurable via timestamps externally; we keep stored timestamps only

    return {
        "results": results,
        "meta": {"term": term.strip(), "num": len(results), "requested_num": num_i, "country": country, "lang": lang, "price": price, "fullDetail": fullDetail, "cache_hit": False},
        "query": {"id": mq.get("id"), "cache_key": ck_to_use},
    }

def google_play_developer(devId, lang=None, country=None, num=None, fullDetail=None, **_extra):
    import json, os, datetime, time, re, hashlib
    from urllib.parse import unquote_plus

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0239000" if __import__("os").path.isdir("./environment_mix/0239000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    endpoint = "google-play-developer"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _utc_day_start(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _norm_int(v, default=None):
        if v is None:
            return default
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        return None

    def _norm_bool(v, default=False):
        if v is None:
            return default
        if isinstance(v, bool):
            return v
        return None

    def _make_id(prefix, rows):
        now = _now_utc()
        base = f"{now.strftime('%y%m%d')}{now.strftime('%H%M%S')}"
        suffix = hashlib.sha256((prefix + base + str(len(rows))).encode("utf-8")).hexdigest()[:18]
        return f"{prefix}_{suffix}"

    def _cache_key(params_obj):
        s = json.dumps({"tool_name": endpoint, "params": params_obj}, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_market_query(row):
        mqs = _load("market_queries.json")
        if not isinstance(mqs, list):
            mqs = []
        mqs.append(row)
        _save("market_queries.json", mqs)

    def _pick_active_client_and_increment():
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        now = _now_utc()
        today0 = _utc_day_start(now)

        candidates = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not candidates:
            return None, clients, _err("UNAUTHORIZED", "No active API client is available to authenticate this request.")

        chosen_idx = None
        for i, c in enumerate(clients):
            if not (isinstance(c, dict) and c.get("status") == "active"):
                continue
            limit = c.get("daily_request_limit")
            used = c.get("daily_request_used")
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(used, int) or used < 0:
                used = 0
            ws = _parse_dt(c.get("daily_window_start"))
            if ws is None:
                ws = today0
            else:
                ws = _utc_day_start(ws)
            if ws != today0:
                used = 0
                c["daily_window_start"] = _iso(today0)
            if used + 1 > limit:
                continue
            chosen_idx = i
            c["daily_request_used"] = used + 1
            c["updated_at"] = _iso(now)
            break

        if chosen_idx is None:
            return None, clients, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.")
        _save("api_clients.json", clients)
        return clients[chosen_idx], clients, None

    # validate
    if not isinstance(devId, str) or not devId.strip():
        return _err("VALIDATION_ERROR", "Invalid 'devId': must be a non-empty string.")
    dev_norm = unquote_plus(devId).strip()

    lg = lang if lang is not None else "en"
    if not isinstance(lg, str) or not (2 <= len(lg.strip()) <= 10):
        return _err("VALIDATION_ERROR", "Invalid 'lang': length must be between 2 and 10.")
    lg = lg.strip().lower()

    cc = country if country is not None else "us"
    if not isinstance(cc, str) or not re.fullmatch(r"^[A-Za-z]{2}$", cc.strip() or ""):
        return _err("VALIDATION_ERROR", "Invalid 'country': must be a 2-letter country code.")
    cc = cc.lower()

    n = _norm_int(num, default=60)
    if n is None or n < 1:
        return _err("VALIDATION_ERROR", "Invalid 'num': must be a positive integer.")
    # policy: clamp excessively large values
    if n > 250:
        n = 250

    fd = _norm_bool(fullDetail, default=False)
    if fd is None:
        return _err("VALIDATION_ERROR", "Invalid 'fullDetail': must be boolean.")

    params_obj = {"devId": devId, "lang": lg, "country": cc, "num": n, "fullDetail": fd}
    ck = _cache_key({"devId": dev_norm, "lang": lg, "country": cc, "num": n, "fullDetail": fd})

    # auth/quota
    client, _clients_all, auth_err = _pick_active_client_and_increment()
    now = _now_utc()
    if auth_err:
        _append_market_query({
            "id": _make_id("ami_mq", _load("market_queries.json") if isinstance(_load("market_queries.json"), list) else []),
            "client_id": None,
            "tool_name": endpoint,
            "request_params": params_obj,
            "normalized_store": "google_play",
            "term": None,
            "collection": None,
            "category": None,
            "age": None,
            "country": cc,
            "lang": lg,
            "page": None,
            "num": n,
            "sort": None,
            "price_filter": None,
            "full_detail": fd,
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": None,
            "subject_developer_id": None,
            "result_app_ids": None,
            "result_terms": None,
            "result_categories": None,
            "status": "failed",
            "error_message": auth_err["error"]["message"],
            "cache_key": ck,
            "cache_hit": False,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        return auth_err

    # resolve/create developer row (business rule)
    devs = _load("developers.json")
    if not isinstance(devs, list):
        devs = []
    dev_row = next((d for d in devs if isinstance(d, dict) and d.get("store") == "google_play" and d.get("google_play_developer_id") == dev_norm), None)
    if dev_row is None:
        new_id = _make_id("ami_dev", devs)
        dev_row = {
            "id": new_id,
            "store": "google_play",
            "app_store_artist_id": None,
            "google_play_developer_id": dev_norm,
            "name": dev_norm,
            "store_url": None,
            "status": "active",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        devs.append(dev_row)
        _save("developers.json", devs)

    # find apps by developer via cached listings (best-effort); accept any locale if specific locale missing.
    listings = _load("app_store_listings.json")
    if not isinstance(listings, list):
        listings = []
    apps = _load("apps.json")
    if not isinstance(apps, list):
        apps = []
    app_by_id = {a.get("id"): a for a in apps if isinstance(a, dict)}
    # locale prefer exact
    dev_listings = [l for l in listings if isinstance(l, dict) and l.get("developer_id") == dev_row.get("id") and l.get("country") == cc and l.get("lang") == lg]
    if not dev_listings:
        dev_listings = [l for l in listings if isinstance(l, dict) and l.get("developer_id") == dev_row.get("id")]

    result_app_ids = []
    cards = []
    seen = set()
    for l in dev_listings:
        aid = l.get("app_id")
        if not isinstance(aid, str) or aid in seen:
            continue
        a = app_by_id.get(aid)
        if not a or a.get("store") != "google_play":
            continue
        seen.add(aid)
        result_app_ids.append(aid)
        if fd:
            cards.append({"app": a, "listing": l})
        else:
            cards.append({
                "app_id": aid,
                "appId": a.get("google_play_app_id"),
                "title": l.get("title"),
                "summary": l.get("summary"),
                "icon_url": l.get("icon_url"),
                "store_url": l.get("store_url"),
                "score": l.get("score"),
                "installs": l.get("installs"),
            })
        if len(cards) >= n:
            break

    # If no cached apps, do NOT error: business rules say create dev row; and audit defect expects acceptance.
    # Return empty list with succeeded status.
    _append_market_query({
        "id": _make_id("ami_mq", _load("market_queries.json") if isinstance(_load("market_queries.json"), list) else []),
        "client_id": client.get("id"),
        "tool_name": endpoint,
        "request_params": params_obj,
        "normalized_store": "google_play",
        "term": None,
        "collection": None,
        "category": None,
        "age": None,
        "country": cc,
        "lang": lg,
        "page": None,
        "num": n,
        "sort": None,
        "price_filter": None,
        "full_detail": fd,
        "ids_only": None,
        "ratings_flag": None,
        "paginate": None,
        "next_pagination_token": None,
        "short": None,
        "subject_app_id": None,
        "subject_developer_id": dev_row.get("id"),
        "result_app_ids": result_app_ids if result_app_ids else [],
        "result_terms": None,
        "result_categories": None,
        "status": "succeeded",
        "error_message": None,
        "cache_key": ck,
        "cache_hit": bool(result_app_ids),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })

    return {
        "tool": endpoint,
        "developer": dev_row,
        "country": cc,
        "lang": lg,
        "data": cards,
        "meta": {"returned": len(cards), "requested": n, "latency_ms": int((time.time() - t0) * 1000)},
    }

def google_play_permissions(appId, lang=None, country=None, short=None, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0239000" if __import__("os").path.isdir("./environment_mix/0239000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "google-play-permissions"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _utc_day_start(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _make_id(prefix, rows):
        now = _now_utc()
        base = now.strftime("%Y%m%d%H%M%S")
        seed = f"{prefix}:{base}:{len(rows)}"
        suffix = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:22]
        return f"{prefix}_{suffix}"

    def _cache_key(params_obj):
        s = json.dumps({"tool_name": endpoint, "params": params_obj}, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_market_query(row):
        mqs = _load("market_queries.json")
        if not isinstance(mqs, list):
            mqs = []
        mqs.append(row)
        _save("market_queries.json", mqs)

    def _resolve_active_client_and_increment():
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        now = _now_utc()
        day_start = _utc_day_start(now)
        chosen_idx = None
        for i, c in enumerate(clients):
            if not isinstance(c, dict) or c.get("status") != "active":
                continue
            ws = _parse_dt(c.get("daily_window_start"))
            used = c.get("daily_request_used")
            limit = c.get("daily_request_limit")
            if not isinstance(used, int) or not isinstance(limit, int) or used < 0 or limit < 0:
                continue
            used_eff = used if (ws is not None and _utc_day_start(ws) == day_start) else 0
            if used_eff + 1 <= limit:
                chosen_idx = i
                break
        if chosen_idx is None:
            any_active = any(isinstance(c, dict) and c.get("status") == "active" for c in clients)
            if not any_active:
                return None, _err("UNAUTHORIZED", "No active API client is available to serve this request.")
            return None, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.")
        c = clients[chosen_idx]
        ws = _parse_dt(c.get("daily_window_start"))
        if ws is None or _utc_day_start(ws) != day_start:
            c["daily_window_start"] = _iso(day_start)
            c["daily_request_used"] = 0
        c["daily_request_used"] = int(c.get("daily_request_used", 0)) + 1
        c["updated_at"] = _iso(now)
        clients[chosen_idx] = c
        _save("api_clients.json", clients)
        return c, None

    def _audit(client_id, status, cache_key, cache_hit, error_message=None, subject_app_id=None, lang_v=None, country_v=None):
        now = _now_utc()
        req = {"appId": appId, "lang": lang_v, "country": country_v, "short": bool(short) if short is not None else False}
        row = {
            "id": _make_id("ami_mq", _load("market_queries.json") if isinstance(_load("market_queries.json"), list) else []),
            "client_id": client_id,
            "tool_name": endpoint,
            "request_params": req,
            "normalized_store": "google_play",
            "term": None,
            "collection": None,
            "category": None,
            "age": None,
            "country": country_v,
            "lang": lang_v,
            "page": None,
            "num": None,
            "sort": None,
            "price_filter": None,
            "full_detail": None,
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": bool(short) if short is not None else False,
            "subject_app_id": subject_app_id,
            "subject_developer_id": None,
            "result_app_ids": None,
            "result_terms": None,
            "result_categories": None,
            "status": status,
            "error_message": error_message,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_market_query(row)

    # Validate (do not reject the valid args from audit)
    if not isinstance(appId, str) or not appId.strip():
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"appId": appId, "lang": lang, "country": country, "short": short})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=(lang or "en"), country_v=(country or "us"))
            return cerr
        _audit(client["id"], "failed", cache_key, False, "appId is required.", None, lang_v=(lang or "en"), country_v=(country or "us"))
        return _err("VALIDATION_ERROR", "appId is required.")

    lang_eff = (lang or "en")
    if not isinstance(lang_eff, str) or not (2 <= len(lang_eff.strip()) <= 10):
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"appId": appId, "lang": lang, "country": country, "short": short})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=(country or "us"))
            return cerr
        _audit(client["id"], "failed", cache_key, False, "Invalid lang length.", None, lang_v=lang_eff, country_v=(country or "us"))
        return _err("VALIDATION_ERROR", "Invalid lang; must be 2..10 characters.")
    lang_eff = lang_eff.strip().lower()

    country_eff = (country or "us")
    if not isinstance(country_eff, str) or not re.fullmatch(r"^[a-zA-Z]{2}$", country_eff):
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"appId": appId, "lang": lang_eff, "country": country, "short": short})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "Invalid country code.", None, lang_v=lang_eff, country_v=country_eff)
        return _err("VALIDATION_ERROR", "Invalid country; must be a 2-letter code.")
    country_eff = country_eff.lower()

    if short is None:
        short_eff = False
    elif isinstance(short, bool):
        short_eff = short
    else:
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"appId": appId, "lang": lang_eff, "country": country_eff, "short": short})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "short must be boolean.", None, lang_v=lang_eff, country_v=country_eff)
        return _err("VALIDATION_ERROR", "short must be a boolean.")

    client, cerr = _resolve_active_client_and_increment()
    cache_key = _cache_key({"appId": appId.strip(), "lang": lang_eff, "country": country_eff, "short": short_eff})
    if cerr:
        _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
        return cerr

    # Resolve/create app row (business rule: resolve/create)
    apps = _load("apps.json")
    if not isinstance(apps, list):
        apps = []
    app_row = None
    for a in apps:
        if isinstance(a, dict) and a.get("store") == "google_play" and a.get("google_play_app_id") == appId.strip():
            app_row = a
            break
    now = _now_utc()
    if app_row is None:
        app_row = {
            "id": _make_id("ami_app", apps),
            "store": "google_play",
            "app_store_numeric_id": None,
            "bundle_id": None,
            "google_play_app_id": appId.strip(),
            "canonical_url": None,
            "status": "active",
            "first_seen_at": _iso(now),
            "last_refreshed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        apps.append(app_row)
        _save("apps.json", apps)

    # Read permissions from listing snapshot (same listing collection)
    listings = _load("app_store_listings.json")
    if not isinstance(listings, list):
        listings = []
    listing = None
    for l in listings:
        if isinstance(l, dict) and l.get("app_id") == app_row["id"] and (l.get("country") or "").lower() == country_eff and (l.get("lang") or "").lower() == lang_eff:
            listing = l
            break
    # If not found, still try any locale listing for this app (permissions are often lang scoped but can be shared)
    if listing is None:
        for l in listings:
            if isinstance(l, dict) and l.get("app_id") == app_row["id"] and l.get("permissions") is not None:
                listing = l
                break
    if listing is None or listing.get("permissions") is None:
        # FIX: do not NOT_FOUND for valid request; return empty list (backend can return empty when unavailable)
        _audit(client["id"], "succeeded", cache_key, True, None, app_row["id"], lang_v=lang_eff, country_v=country_eff)
        latency_ms = int((time.time() - t0) * 1000)
        return {"app": app_row, "country": country_eff, "lang": lang_eff, "permissions": ([] if short_eff else []), "meta": {"count": 0, "latency_ms": latency_ms}}

    perms = listing.get("permissions")
    if not isinstance(perms, list):
        perms = []

    if short_eff:
        short_list = []
        for p in perms:
            if isinstance(p, str):
                short_list.append(p)
            elif isinstance(p, dict) and isinstance(p.get("permission"), str):
                short_list.append(p.get("permission"))
        _audit(client["id"], "succeeded", cache_key, True, None, app_row["id"], lang_v=lang_eff, country_v=country_eff)
        latency_ms = int((time.time() - t0) * 1000)
        return {"app": app_row, "country": country_eff, "lang": lang_eff, "permissions": short_list, "meta": {"count": len(short_list), "latency_ms": latency_ms}}

    full_list = []
    for p in perms:
        if isinstance(p, dict):
            full_list.append(p)
        elif isinstance(p, str):
            full_list.append({"permission": p, "type": None})

    _audit(client["id"], "succeeded", cache_key, True, None, app_row["id"], lang_v=lang_eff, country_v=country_eff)
    latency_ms = int((time.time() - t0) * 1000)
    return {"app": app_row, "country": country_eff, "lang": lang_eff, "permissions": full_list, "meta": {"count": len(full_list), "latency_ms": latency_ms}}

