        return _err("VALIDATION_ERROR", "appId is required.")

    lang_eff = (lang or "en")
    if not isinstance(lang_eff, str) or not (2 <= len(lang_eff.strip()) <= 10):
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"appId": appId, "lang": lang})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "Invalid lang length.", None, lang_v=lang_eff)
        return _err("VALIDATION_ERROR", "Invalid lang; must be 2..10 characters.")
    lang_eff = lang_eff.strip().lower()

    client, cerr = _resolve_active_client_and_increment()
    cache_key = _cache_key({"appId": appId.strip(), "lang": lang_eff})
    if cerr:
        _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff)
        return cerr

    # Resolve/create app row (business rule)
    apps = _load("apps.json")
    if not isinstance(apps, list):
        apps = []
    app_row = None
    for a in apps:
        if isinstance(a, dict) and a.get("store") == "google_play" and a.get("google_play_app_id") == appId.strip():
            app_row = a
            break
    now = _now_utc()
    if app_row is None:
        app_row = {
            "id": _make_id("ami_app", apps),
            "store": "google_play",
            "app_store_numeric_id": None,
            "bundle_id": None,
            "google_play_app_id": appId.strip(),
            "canonical_url": None,
            "status": "active",
            "first_seen_at": _iso(now),
            "last_refreshed_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        apps.append(app_row)
        _save("apps.json", apps)

    # Read data safety from listing snapshot (any locale match acceptable; lang scoped preferred)
    listings = _load("app_store_listings.json")
    if not isinstance(listings, list):
        listings = []
    listing = None
    for l in listings:
        if isinstance(l, dict) and l.get("app_id") == app_row["id"] and (l.get("lang") or "").lower() == lang_eff and l.get("data_safety") is not None:
            listing = l
            break
    if listing is None:
        for l in listings:
            if isinstance(l, dict) and l.get("app_id") == app_row["id"] and l.get("data_safety") is not None:
                listing = l
                break

    # FIX: do not NOT_FOUND for valid request; return empty object when unavailable
    data = listing.get("data_safety") if isinstance(listing, dict) else None
    if data is None:
        data = {}

    _audit(client["id"], "succeeded", cache_key, True, None, app_row["id"], lang_v=lang_eff)
    latency_ms = int((time.time() - t0) * 1000)
    return {"app": app_row, "lang": lang_eff, "dataSafety": data, "meta": {"latency_ms": latency_ms}}

def google_play_categories(lang=None, country=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0239000" if __import__("os").path.isdir("./environment_mix/0239000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0)
    today = datetime.datetime(now.year, now.month, now.day)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            return dt.replace(microsecond=0).isoformat() + "Z"
        return dt

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, (int, float)):
            return datetime.datetime.utcfromtimestamp(v)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1]
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _audit(client_id, status, cache_hit=False, error_message=None, cache_key=None, result_categories=None):
        mq = _load("market_queries.json")
        qid = "mq_" + uuid.uuid4().hex
        row = {
            "id": qid,
            "client_id": client_id,
            "tool_name": "google-play-categories",
            "request_params": {"lang": lang, "country": country},
            "normalized_store": "google_play",
            "term": None,
            "collection": None,
            "category": None,
            "age": None,
            "country": country,
            "lang": lang,
            "page": None,
            "num": None,
            "sort": None,
            "price_filter": None,
            "full_detail": None,
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": None,
            "subject_developer_id": None,
            "result_app_ids": None,
            "result_terms": None,
            "result_categories": result_categories,
            "status": status,
            "error_message": error_message,
            "cache_key": cache_key or "",
            "cache_hit": bool(cache_hit),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        mq.append(row)
        _save("market_queries.json", mq)

    def _pick_active_client_and_charge():
        clients = _load("api_clients.json")
        active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API client available.")
        for c in active:
            ws = _parse_dt(c.get("daily_window_start"))
            if ws is None or ws != today:
                c["daily_window_start"] = _iso(today)
                c["daily_request_used"] = 0
            limit = c.get("daily_request_limit")
            used = c.get("daily_request_used")
            if not isinstance(limit, int) or limit < 0:
                continue
            if not isinstance(used, int) or used < 0:
                used = 0
                c["daily_request_used"] = 0
            if used + 1 <= limit:
                c["daily_request_used"] = used + 1
                c["updated_at"] = _iso(now)
                _save("api_clients.json", clients)
                return c, None
        _save("api_clients.json", clients)
        return None, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.")

    # validate
    if lang is not None:
        if not isinstance(lang, str) or not (2 <= len(lang) <= 10):
            client, e = _pick_active_client_and_charge()
            if client:
                _audit(client["id"], "failed", cache_hit=False, error_message="VALIDATION_ERROR: lang")
            return _err("VALIDATION_ERROR", "lang must be a string length 2..10.")
    if country is not None:
        if not isinstance(country, str) or not re.fullmatch(r"[A-Za-z]{2}", country or ""):
            client, e = _pick_active_client_and_charge()
            if client:
                _audit(client["id"], "failed", cache_hit=False, error_message="VALIDATION_ERROR: country")
            return _err("VALIDATION_ERROR", "country must be a 2-letter code.")

    client, err = _pick_active_client_and_charge()
    if err:
        if err["error"]["code"] != "UNAUTHORIZED":
            clients = _load("api_clients.json")
            active = [c for c in clients if isinstance(c, dict) and c.get("status") == "active"]
            if active:
                _audit(active[0]["id"], "failed", cache_hit=False, error_message=err["error"]["message"])
        return err

    # canonical static list from tool enum (stored as identifiers)
    categories = [
        "APPLICATION", "ANDROID_WEAR", "ART_AND_DESIGN", "AUTO_AND_VEHICLES", "BEAUTY", "BOOKS_AND_REFERENCE",
        "BUSINESS", "COMICS", "COMMUNICATION", "DATING", "EDUCATION", "ENTERTAINMENT", "EVENTS", "FINANCE",
        "FOOD_AND_DRINK", "HEALTH_AND_FITNESS", "HOUSE_AND_HOME", "LIBRARIES_AND_DEMO", "LIFESTYLE",
        "MAPS_AND_NAVIGATION", "MEDICAL", "MUSIC_AND_AUDIO", "NEWS_AND_MAGAZINES", "PARENTING",
        "PERSONALIZATION", "PHOTOGRAPHY", "PRODUCTIVITY", "SHOPPING", "SOCIAL", "SPORTS", "TOOLS",
        "TRAVEL_AND_LOCAL", "VIDEO_PLAYERS", "WATCH_FACE", "WEATHER",
        "GAME", "GAME_ACTION", "GAME_ADVENTURE", "GAME_ARCADE", "GAME_BOARD", "GAME_CARD", "GAME_CASINO",
        "GAME_CASUAL", "GAME_EDUCATIONAL", "GAME_MUSIC", "GAME_PUZZLE", "GAME_RACING", "GAME_ROLE_PLAYING",
        "GAME_SIMULATION", "GAME_SPORTS", "GAME_STRATEGY", "GAME_TRIVIA", "GAME_WORD",
        "FAMILY",
    ]

    norm = {"lang": (lang or "").lower(), "country": (country or "").lower()}
    cache_key = "google-play-categories:" + hashlib.sha256(json.dumps(norm, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    _audit(client["id"], "succeeded", cache_hit=True, cache_key=cache_key, result_categories=categories)
    return {"categories": categories, "lang": lang, "country": country, "meta": {"cache_hit": True}}

def google_play_list(collection=None, category=None, age=None, num=None, lang=None, country=None, fullDetail=None, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0239000" if __import__("os").path.isdir("./environment_mix/0239000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    endpoint = "google-play-list"
    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _utc_day_start(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)

    def _norm_int(v, default=None):
        if v is None:
            return default
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, float) and v.is_integer():
            return int(v)
        if isinstance(v, str) and v.strip().isdigit():
            try:
                return int(v.strip())
            except Exception:
                return None
        return None

    def _make_id(prefix, rows):
        now = _now_utc()
        base = now.strftime("%Y%m%d%H%M%S")
        seed = f"{prefix}:{base}:{len(rows)}"
        suffix = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:22]
        return f"{prefix}_{suffix}"

    def _cache_key(params_obj):
        s = json.dumps({"tool_name": endpoint, "params": params_obj}, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _append_market_query(row):
        mqs = _load("market_queries.json")
        if not isinstance(mqs, list):
            mqs = []
        mqs.append(row)
        _save("market_queries.json", mqs)

    def _resolve_active_client_and_increment():
        clients = _load("api_clients.json")
        if not isinstance(clients, list):
            clients = []
        now = _now_utc()
        day_start = _utc_day_start(now)
        chosen_idx = None
        for i, c in enumerate(clients):
            if not isinstance(c, dict) or c.get("status") != "active":
                continue
            ws = _parse_dt(c.get("daily_window_start"))
            used = c.get("daily_request_used")
            limit = c.get("daily_request_limit")
            if not isinstance(used, int) or not isinstance(limit, int) or used < 0 or limit < 0:
                continue
            used_eff = used if (ws is not None and _utc_day_start(ws) == day_start) else 0
            if used_eff + 1 <= limit:
                chosen_idx = i
                break
        if chosen_idx is None:
            any_active = any(isinstance(c, dict) and c.get("status") == "active" for c in clients)
            if not any_active:
                return None, _err("UNAUTHORIZED", "No active API client is available to serve this request.")
            return None, _err("QUOTA_EXCEEDED", "Daily request limit exceeded.")
        c = clients[chosen_idx]
        ws = _parse_dt(c.get("daily_window_start"))
        if ws is None or _utc_day_start(ws) != day_start:
            c["daily_window_start"] = _iso(day_start)
            c["daily_request_used"] = 0
        c["daily_request_used"] = int(c.get("daily_request_used", 0)) + 1
        c["updated_at"] = _iso(now)
        clients[chosen_idx] = c
        _save("api_clients.json", clients)
        return c, None

    def _audit(client_id, status, cache_key, cache_hit, error_message=None, result_app_ids=None, lang_v=None, country_v=None):
        now = _now_utc()
        req = {"collection": collection, "category": category, "age": age, "num": num, "lang": lang_v, "country": country_v, "fullDetail": bool(fullDetail) if fullDetail is not None else False}
        row = {
            "id": _make_id("ami_mq", _load("market_queries.json") if isinstance(_load("market_queries.json"), list) else []),
            "client_id": client_id,
            "tool_name": endpoint,
            "request_params": req,
            "normalized_store": "google_play",
            "term": None,
            "collection": collection,
            "category": category,
            "age": age,
            "country": country_v,
            "lang": lang_v,
            "page": None,
            "num": _norm_int(num, default=None),
            "sort": None,
            "price_filter": None,
            "full_detail": bool(fullDetail) if fullDetail is not None else False,
            "ids_only": None,
            "ratings_flag": None,
            "paginate": None,
            "next_pagination_token": None,
            "short": None,
            "subject_app_id": None,
            "subject_developer_id": None,
            "result_app_ids": result_app_ids,
            "result_terms": None,
            "result_categories": None,
            "status": status,
            "error_message": error_message,
            "cache_key": cache_key,
            "cache_hit": bool(cache_hit),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _append_market_query(row)

    # Defaults per schema
    collection = collection or "TOP_FREE"
    lang_eff = (lang or "en")
    country_eff = (country or "us")
    num_i = _norm_int(num, default=500)
    if fullDetail is None:
        fullDetail_eff = False
    elif isinstance(fullDetail, bool):
        fullDetail_eff = fullDetail
    else:
        # still must audit; but authenticate/quota first
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"collection": collection, "category": category, "age": age, "num": num, "lang": lang, "country": country, "fullDetail": fullDetail})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "fullDetail must be boolean.", None, lang_v=lang_eff, country_v=country_eff)
        return _err("VALIDATION_ERROR", "fullDetail must be a boolean.")

    # Validate enums (category is required by API behavior; treat missing as VALIDATION_ERROR)
    valid_collections = {"TOP_FREE", "TOP_PAID", "GROSSING", "TOP_FREE_GAMES", "TOP_PAID_GAMES", "TOP_GROSSING_GAMES"}
    if collection not in valid_collections:
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"collection": collection, "category": category, "age": age, "num": num_i, "lang": lang_eff, "country": country_eff, "fullDetail": fullDetail_eff})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "Invalid collection enum.", None, lang_v=lang_eff, country_v=country_eff)
        return _err("VALIDATION_ERROR", "Invalid collection.")

    # category is required by vendor behavior (schema doesn't mark required, but description implies); accept if provided else default APPLICATION
    if category is None:
        category = "APPLICATION"

    valid_categories = {
        "APPLICATION","ANDROID_WEAR","ART_AND_DESIGN","AUTO_AND_VEHICLES","BEAUTY","BOOKS_AND_REFERENCE","BUSINESS","COMICS","COMMUNICATION","DATING",
        "EDUCATION","ENTERTAINMENT","EVENTS","FINANCE","FOOD_AND_DRINK","HEALTH_AND_FITNESS","HOUSE_AND_HOME","LIBRARIES_AND_DEMO","LIFESTYLE",
        "MAPS_AND_NAVIGATION","MEDICAL","MUSIC_AND_AUDIO","NEWS_AND_MAGAZINES","PARENTING","PERSONALIZATION","PHOTOGRAPHY","PRODUCTIVITY","SHOPPING",
        "SOCIAL","SPORTS","TOOLS","TRAVEL_AND_LOCAL","VIDEO_PLAYERS","WATCH_FACE","WEATHER",
        "GAME","GAME_ACTION","GAME_ADVENTURE","GAME_ARCADE","GAME_BOARD","GAME_CARD","GAME_CASINO","GAME_CASUAL","GAME_EDUCATIONAL","GAME_MUSIC","GAME_PUZZLE",
        "GAME_RACING","GAME_ROLE_PLAYING","GAME_SIMULATION","GAME_SPORTS","GAME_STRATEGY","GAME_TRIVIA","GAME_WORD",
        "FAMILY"
    }
    if category not in valid_categories:
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"collection": collection, "category": category, "age": age, "num": num_i, "lang": lang_eff, "country": country_eff, "fullDetail": fullDetail_eff})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "Invalid category enum.", None, lang_v=lang_eff, country_v=country_eff)
        return _err("VALIDATION_ERROR", "Invalid category.")

    # FIX: age is allowed only when category='FAMILY'; but do not reject when present with FAMILY (audit defect was wrong rejection policy)
    if age is not None:
        valid_ages = {"FIVE_UNDER", "SIX_EIGHT", "NINE_UP"}
        if age not in valid_ages:
            client, cerr = _resolve_active_client_and_increment()
            cache_key = _cache_key({"collection": collection, "category": category, "age": age, "num": num_i, "lang": lang_eff, "country": country_eff, "fullDetail": fullDetail_eff})
            if cerr:
                _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
                return cerr
            _audit(client["id"], "failed", cache_key, False, "Invalid age enum.", None, lang_v=lang_eff, country_v=country_eff)
            return _err("VALIDATION_ERROR", "Invalid age.")
        if category != "FAMILY":
            # policy: accept but ignore age (clamp/ignore is allowed by implementation policy)
            age_eff = None
        else:
            age_eff = age
    else:
        age_eff = None

    # Validate locale and num (clamp to 500 default; schema default says 500; no explicit max in rules)
    if not isinstance(lang_eff, str) or not (2 <= len(lang_eff.strip()) <= 10):
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"collection": collection, "category": category, "age": age_eff, "num": num_i, "lang": lang_eff, "country": country_eff, "fullDetail": fullDetail_eff})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "Invalid lang length.", None, lang_v=lang_eff, country_v=country_eff)
        return _err("VALIDATION_ERROR", "Invalid lang; must be 2..10 characters.")
    lang_eff = lang_eff.strip().lower()

    if not isinstance(country_eff, str) or not re.fullmatch(r"^[a-zA-Z]{2}$", country_eff):
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"collection": collection, "category": category, "age": age_eff, "num": num_i, "lang": lang_eff, "country": country_eff, "fullDetail": fullDetail_eff})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "Invalid country code.", None, lang_v=lang_eff, country_v=country_eff)
        return _err("VALIDATION_ERROR", "Invalid country; must be a 2-letter code.")
    country_eff = country_eff.lower()

    if num_i is None or num_i < 1:
        client, cerr = _resolve_active_client_and_increment()
        cache_key = _cache_key({"collection": collection, "category": category, "age": age_eff, "num": num, "lang": lang_eff, "country": country_eff, "fullDetail": fullDetail_eff})
        if cerr:
            _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
            return cerr
        _audit(client["id"], "failed", cache_key, False, "num must be >= 1.", None, lang_v=lang_eff, country_v=country_eff)
        return _err("VALIDATION_ERROR", "num must be >= 1.")
    # Clamp very high values to 500 per schema default usage style
    if num_i > 500:
        num_i = 500

    client, cerr = _resolve_active_client_and_increment()
    cache_key = _cache_key({"collection": collection, "category": category, "age": age_eff, "num": num_i, "lang": lang_eff, "country": country_eff, "fullDetail": fullDetail_eff})
    if cerr:
        _audit("unknown", "failed", cache_key, False, cerr["error"]["message"], None, lang_v=lang_eff, country_v=country_eff)
        return cerr

    # Best-effort list from cache: choose google_play apps and return their locale listing cards if available
    apps = _load("apps.json")
    if not isinstance(apps, list):
        apps = []
    gp_apps = [a for a in apps if isinstance(a, dict) and a.get("store") == "google_play" and a.get("status") == "active"]
    if not gp_apps:
        _audit(client["id"], "failed", cache_key, True, "No cached Google Play apps available.", [], lang_v=lang_eff, country_v=country_eff)
        return _err("NOT_FOUND", "No apps available for this collection/category in cache.")

    # Deterministic shuffle based on cache_key
    seed = hashlib.sha256(cache_key.encode("utf-8")).hexdigest()
    gp_apps.sort(key=lambda a: hashlib.sha256((seed + a.get("id", "")).encode("utf-8")).hexdigest())
    selected = gp_apps[:num_i]

    listings = _load("app_store_listings.json")
    if not isinstance(listings, list):
        listings = []
    listing_map = {}
    for l in listings:
