        if (l.get("country") or "").lower() != country_eff:
            continue
        if (l.get("lang") or "").lower() != lang_eff:
            continue
        if l.get("app_id"):
            listing_map[l.get("app_id")] = l

    results = []
    result_app_ids = []
    for a in selected:
        aid = a.get("id")
        if not aid:
            continue
        card = {"app": a}
        l = listing_map.get(aid)
        if l is not None:
            card.update({
                "title": l.get("title"),
                "summary": l.get("summary"),
                "icon": l.get("icon_url"),
                "url": l.get("store_url") or a.get("canonical_url"),
                "score": l.get("score"),
                "priceText": l.get("price_text"),
                "free": l.get("is_free"),
            })
            if fullDetail_eff:
                card["details"] = {
                    "description": l.get("description"),
                    "descriptionHTML": l.get("description_html"),
                    "installs": l.get("installs"),
                    "minInstalls": l.get("min_installs"),
                    "maxInstalls": l.get("max_installs"),
                    "permissions": l.get("permissions"),
                    "dataSafety": l.get("data_safety"),
                }
        results.append(card)
        result_app_ids.append(aid)

    _audit(client["id"], "succeeded", cache_key, True, None, result_app_ids=result_app_ids, lang_v=lang_eff, country_v=country_eff)
    latency_ms = int((time.time() - t0) * 1000)
    return {
        "collection": collection,
        "category": category,
        "age": age_eff,
        "country": country_eff,
        "lang": lang_eff,
        "fullDetail": fullDetail_eff,
        "results": results,
        "meta": {"count": len(results), "latency_ms": latency_ms},
    }
